// ─── INPUTS ───────────────────────────────────────────────
// NPD product from the loop
const product = $('Loop Over NPD Products').item.json;

// All margin sheet rows
const marginRows = $input.all();

// ─── EXTRACT PRODUCT FIELDS ───────────────────────────────
const brand        = (product['Brand'] || '').trim();
const productName  = (product['Product'] || '').trim();
const sapCode      = String(product['SAP code'] || '').trim();
const skuCode      = (product['SKU code 1'] || '').trim();
const sku2         = (product['SKU code 2'] || '').trim();
const barcode      = String(product['Barcode'] || '').trim();
const size         = (product['Size'] || '').trim();
const description  = (product['Product description'] || product['Product'] || '').trim();
const category     = (product['CATEGORY'] || '').trim();
const subcat1      = (product['SUBCAT1'] || '').trim();
const subcat2      = (product['SUBCAT2 (BestSeller)'] || product['SUBCAT2'] || '').trim();
const currency     = (product["Supplier's currency"] || 'EUR').trim();
const landingCost  = product['Landing Cost, EUR'] || product['Landing Cost, EUR'] || 0;
const rrpEuro      = product['RRP EURO'] || 0;
const rrpExclVat   = product['RRP EUR excl VAT'] || 0;
const wholesale    = product['Wholesale, EUR'] || product['Wholesale EUR'] || 0;
const operatorFee  = product['Operator fees, %'] || 0;
const skuStatus    = (product['SKU status'] || '').trim();
const countryRaw   = (product['Country Of Origin'] || product['Country of Origin'] || '').trim();
const country      = countryRaw.replace(/^From\s+/i, '').trim();
const commodityCode = String(product['European Commodity Code'] || '').trim();
const cduSize      = product['Units per Inner Case'] || '';

// Derived fields
const isNPD    = skuStatus.toUpperCase().includes('NPD') ? 'Yes' : 'No';
const isActive = (['DISC','ZZ'].some(s => skuStatus.toUpperCase().startsWith(s))) ? 'false' : 'true';

// ─── MATCH BRAND IN MARGIN SHEET ──────────────────────────
// Margin sheet columns: K=Customer, L=Brand, M=% off RRP (decimal e.g. 0.33), N=Listed
const brandLower = brand.toLowerCase();

const matchingMargins = marginRows
  .map(r => r.json)
  .filter(r => {
    const mBrand = (r['Brand'] || r['L'] || '').toString().trim().toLowerCase();
    return mBrand === brandLower;
  })
  .filter(r => {
    // Only use rows where margin is a valid number
    const m = r['% off RRP'] || r['M'] || r[Object.keys(r)[12]];
    return m !== '' && m !== null && m !== undefined && !isNaN(parseFloat(m));
  });

// ─── BUILD OUTPUT ITEMS (one per customer, or one standard) ─
const outputItems = [];

if (matchingMargins.length > 0) {
  // BESPOKE: create one pricebook entry per customer found
  for (const marginRow of matchingMargins) {
    const customer   = (marginRow['Customer'] || marginRow['K'] || '').toString().trim();
    const marginVal  = parseFloat(marginRow['% off RRP'] || marginRow['M'] || '0');
    const listed     = (marginRow['Listed'] || marginRow['N'] || '').toString().trim();

    const calcPrice  = parseFloat((rrpExclVat * (1 - marginVal)).toFixed(2));
    const pricebookName = customer + ' Pricebook';

    outputItems.push({
      // ── Meta ──
      pricingType:    'Bespoke',
      customer:       customer,
      marginPct:      marginVal,
      marginDisplay:  (marginVal * 100).toFixed(1) + '%',
      listed:         listed,

      // ── Product fields ──
      brand,
      productName,
      sapCode,
      skuCode,
      sku2,
      barcode,
      size,
      description,
      category,
      subcat1,
      subcat2,
      currency,
      landingCost,
      rrpEuro,
      rrpExclVat,
      wholesale,
      operatorFee,
      skuStatus,
      country,
      commodityCode,
      cduSize,
      isNPD,
      isActive,

      // ── Pricebook entry fields ──
      pricebookName,
      calculatedPrice: calcPrice,
      useStandardPrice: 'No'
    });
  }
} else {
  // STANDARD: no margin rule found — use wholesale price directly
  const calcPrice = parseFloat(parseFloat(wholesale).toFixed(2));

  outputItems.push({
    // ── Meta ──
    pricingType:    'Standard',
    customer:       'STANDARD',
    marginPct:      null,
    marginDisplay:  'Standard',
    listed:         '',

    // ── Product fields ──
    brand,
    productName,
    sapCode,
    skuCode,
    sku2,
    barcode,
    size,
    description,
    category,
    subcat1,
    subcat2,
    currency,
    landingCost,
    rrpEuro,
    rrpExclVat,
    wholesale,
    operatorFee,
    skuStatus,
    country,
    commodityCode,
    cduSize,
    isNPD,
    isActive,

    // ── Pricebook entry fields ──
    pricebookName:   'Standard Pricebook',
    calculatedPrice: calcPrice,
    useStandardPrice: 'Yes'
  });
}

return outputItems;
